namespace Sws2Cs2Menus.Contracts;

/// <summary>
/// Fluent builder for an <see cref="IMenuDefinition"/>.
/// </summary>
public interface IMenuBuilder
{
    /// <summary>Sets a stable menu identifier. A unique id is generated by default.</summary>
    IMenuBuilder Id(string id);

    /// <summary>Sets an optional comment shown under the title.</summary>
    IMenuBuilder Comment(string? comment);

    /// <summary>Sets the number of options per page. Values are clamped to 1-5.</summary>
    IMenuBuilder PageSize(int pageSize);

    /// <summary>Requires a permission before the menu can be opened.</summary>
    IMenuBuilder Permission(string? permission);

    /// <summary>Enables or disables the Back action when the menu has a parent.</summary>
    IMenuBuilder ShowBack(bool show = true);

    /// <summary>Enables or disables closing the menu.</summary>
    IMenuBuilder ShowClose(bool show = true);

    /// <summary>Whether selecting a regular option closes the menu. Defaults to true.</summary>
    IMenuBuilder CloseOnSelect(bool close = true);

    /// <summary>Sets a callback invoked when this menu is closed for a player.</summary>
    IMenuBuilder OnClosed(Func<MenuContext, ValueTask>? handler);

    /// <summary>Adds an option.</summary>
    IMenuBuilder AddOption(string id, string text, Func<MenuOptionContext, ValueTask>? onSelected = null);

    /// <summary>Adds an option configured through a nested builder.</summary>
    IMenuBuilder AddOption(Action<IMenuOptionBuilder> configure);

    /// <summary>Adds an already built option.</summary>
    IMenuBuilder AddOption(IMenuOptionDefinition option);

    /// <summary>Adds an option that opens another menu.</summary>
    IMenuBuilder AddSubMenu(string id, string text, IMenuDefinition subMenu);

    /// <summary>Builds the immutable menu definition.</summary>
    IMenuDefinition Build();
}

/// <summary>
/// Fluent builder for an <see cref="IMenuOptionDefinition"/>.
/// </summary>
public interface IMenuOptionBuilder
{
    /// <summary>Sets a stable option identifier. A unique id is generated by default.</summary>
    IMenuOptionBuilder Id(string id);

    /// <summary>Sets the displayed text.</summary>
    IMenuOptionBuilder Text(string text);

    /// <summary>Sets an optional comment.</summary>
    IMenuOptionBuilder Comment(string? comment);

    /// <summary>Sets the text colour in #RRGGBB format.</summary>
    IMenuOptionBuilder Color(string? hexColor);

    /// <summary>Requires a permission before this option is shown.</summary>
    IMenuOptionBuilder Permission(string? permission);

    /// <summary>Shows the option but prevents selection.</summary>
    IMenuOptionBuilder Disabled(bool disabled = true);

    /// <summary>Hides the option entirely.</summary>
    IMenuOptionBuilder Hidden(bool hidden = true);

    /// <summary>Associates caller data with the option.</summary>
    IMenuOptionBuilder Tag(object? tag);

    /// <summary>Sets the selection callback.</summary>
    IMenuOptionBuilder OnSelected(Func<MenuOptionContext, ValueTask>? handler);

    /// <summary>Opens a submenu when this option is selected.</summary>
    IMenuOptionBuilder SubMenu(IMenuDefinition? subMenu);

    /// <summary>Builds the immutable option definition.</summary>
    IMenuOptionDefinition Build();
}
